# Website-only Captain workflow migration. Scenario bindings are generated by Chatwoot from tool:// links.
require 'digest'

module WebsiteSupportRouting
  ORDERS = '[@本人订单](tool://custom_xboard_orders)'
  CONNECTION = '[@本人套餐与用量](tool://custom_xboard_connection)'
  PLANS = '[@在售套餐](tool://custom_xboard_plans)'
  OFFERS = '[@公告与活动](tool://custom_xboard_notices_and_offers)'
  QUOTE = '[@优惠试算](tool://custom_xboard_coupon_quote)'

  USAGE = "流量包、流量余额、钱包余额、扣量异常、线路倍率、充值赠送或保底扣量：先调用 #{CONNECTION}，传 detail=usage。区分实付金额、购买及赠送的 GB、估算实际用量和按倍率计费用量。说明统计周期；按现价折合的钱包余量不是账户现金余额；没有明细时不要猜测。"
  PURCHASE = "涉及购买或支付记录（如「买了 50 元怎么只剩这些流量」）时，同时调用 #{ORDERS}；未提供完整订单号时不传 trade_no，先核对本人近期订单、实付与入账。订单与用量都需查询时，两项都返回后再答复。"
  DIAGNOSIS = "用户反馈本人无法连接、节点缺失或到期时，先调用 #{CONNECTION}（省略 detail，可按节点名称传 node），再决定客户端排查或索图。节点上报正常仅说明有心跳。"
  CATALOG = "当前套餐、价格和权益用 #{PLANS}；公告和已披露优惠用 #{OFFERS}；客户指定套餐与周期后用 #{QUOTE} 试算。一般政策与客户端步骤参考 FAQ。"
  SOURCE = '个人事实仅采用本次网站会话的 XBoard 只读结果。若需登录，请客户在面板登录后从原网页重试。不要用联系人旧字段、客户自报邮箱或截图验证身份。'
  EVIDENCE = '先核实能查询到的记录；已有截图或已提供的信息不重复索取。只有仍有具体差异时才问缺少的一项，必要的脱敏凭证在面板服务工单提交。工具只读，面板工单由人工处理。'
  MAIN_GUIDE = [USAGE, PURCHASE, DIAGNOSIS, CATALOG].join("\n").gsub(/\[@[^\]]+\]\(tool:\/\/([^\)]+)\)/, '`\1`')
  MAIN_GUARD = "#{SOURCE} #{EVIDENCE}"
  HEADING = '# 网站实时业务查询'
  SCENARIOS = {
    '故障排查引导' => :general,
    'Clash Verge 专项修复（DNS Rewrite）' => :connection,
    'flclash 节点优化引导' => :connection,
    'Shadowrocket (小火箭) 专项故障排查工作流' => :connection,
    '新手使用引导' => :onboarding,
    '支付 / 订单 / 套餐异常' => :billing,
    '规则 / 价格 / 套餐咨询（FAQ 优先）' => :catalog
  }.freeze

  # Only replace the exact legacy instructions inspected on the website. Preserve unrelated
  # branding, operational priorities, ticket escalation, and any edits outside the matched text.
  LEGACY_SECTIONS = %w[
    e55552f5a7ff35a832717e818df908697d7e7602e8d40cc1bfcfd83a3c971057
    3ae28438318f61548a5f1bee5f5e60cb54738925c16a535aeb40d762953735c6
    ba096b2ce7e74a12c01bd3ee7c9ac20ce0fbd6f84b7ca059069d23f179caef53
    47352fd4dd02d6b091a35c44a375d3031042a9b9df51d0f545efc3c05065a49d
    80b80b738835fd86b29ace83ee97ec94018c2e0f00fd84f299521c3abc8627af
    df22b0817977f58d36d8419b233944c8654bf82db4f58fc88c035affe1274c18
    f12b4ef64b6d9ba8605c6944a9384a5f5907c0d300cf1b7f3dd56d261fcc8156
  ].freeze
  # Old guidelines and guardrails that said to trust the contact snapshot or request proof first.
  LEGACY_RULES = %w[
    b1a4a6f252a3b6d3bc36e52ae9b05cae3461e4abe4164eb2c623cd4080df28b3
    03cc072a5493e15c0d624da4e9bb947a4574d3c962ec2f1032f6b9170438df3b
    7c28af02ea9f21231b49e94be989d7ec67acef84eb51e7d3154b11a22dc69794
    b8c0de44f42212f329d742588a121220718496d85333dc2b91fa0042ed3802fd
    d2e6d40c2f862d243525cf01646ff6ff5151fc9bf93116a5b19ddb8b55e6d899
    94c47f7c11f73611228402cefc4c81b53f22bb04fe20fa78611ceb510f527b63
    2af5fb072d811b5a027583ebf151e7ceed172784f1c26e5e3b7cd492aa084818
    8eeeee5ae0eee0092b0b58602f60bdd94d27d2cb1e5372c6bcb09d032f911571
    d6b574442d9c51346c8f28a8d80c2ec980b83c79facf572c7c2ffcba3cda01b9
  ].freeze
  TECH_REMINDERS = '如实时结果显示到期、封禁或流量耗尽，优先解释相应状态。有效套餐距到期不超过七天时可提醒续费，流量使用达到 90% 时可提醒查看剩余额度。保持苏菲一贯温柔亲切的语气，适当使用 Emoji。'

  def self.master_rules(rules, required)
    kept = Array(rules).reject { |text| LEGACY_RULES.include?(Digest::SHA256.hexdigest(text)) }.map do |text|
      text.sub('回答前先调用 captain--tools--faq_lookup 在知识库里检索相关内容，找不到再考虑追问。', '一般政策、教程先查 FAQ；涉及本人账户时先查对应网站业务工具，再用 FAQ 解释规则。')
          .sub('FAQ + xboard 字段 + 专项排查', 'FAQ + 网站实时业务查询 + 专项排查')
          .sub('需查后台订单 / 需技术核查节点', '实时结果与凭证不一致需后台对账 / 需技术核查节点')
    end
    kept + (required - kept)
  end

  def self.replace_reviewed(text, pattern, replacement = '')
    text.sub(pattern) do |section|
      unless LEGACY_SECTIONS.include?(Digest::SHA256.hexdigest(section))
        raise "Website scenario has edited legacy instructions; review section #{section.lines.first.strip}"
      end

      replacement
    end
  end

  def self.instructions(kind, original)
    text = replace_reviewed(original, /^# 进入本场景前必做：检查 contact 已有字段\n.*?(?=^---\n)/m)
    text = replace_reviewed(text, /^# 利用 contact .*?(?=^# 升级与服务工单)/m)
    if kind == :billing
      text = replace_reviewed(text, /^流程：\n\n1\. 先用 .*?(?=^4\. 用户提供完信息后：)/m,
                              "对账流程按上方网站实时业务查询执行。如仍需人工核对，请客户在工单内提交所缺凭证。\n\n")
      text = text.sub('4. 用户提供完信息后：', '仅在核对后仍需建单时：')
    end
    if kind == :catalog
      text = text.sub('叠加规则、价格、续费天数等必须以 FAQ 为准', '一般规则参考 FAQ，现价和个人到期时间查看网站实时结果')
    end
    lines = case kind
            when :billing
              ['尚未下单且仅提示「暂无可用支付方式」时，直接依照已有专门流程排查支付页面。', PURCHASE, USAGE,
               "询问已购套餐到期或权益时，再用 #{CONNECTION} 省略 detail 查看当前资格。"]
            when :catalog
              [CATALOG, USAGE, PURCHASE, "比较本人现有套餐时用 #{CONNECTION} 查询当前权益。"]
            when :onboarding
              ['一般下载、导入教程直接查 FAQ；用户询问已购权益或遇到实际连接异常时使用本节查询。', DIAGNOSIS, USAGE]
            when :general
              [DIAGNOSIS, USAGE, PURCHASE]
            when :connection
              [DIAGNOSIS, USAGE]
            end
    lines << '同时涉及付款、到账或订单差异时，回到主助手进入支付/订单场景核对订单和入账。' if %i[connection onboarding].include?(kind)
    block = ([HEADING] + lines + [SOURCE, EVIDENCE]).join("\n")
    return text.sub(/\A#{Regexp.escape(HEADING)}\n[^\n]+(?:\n[^\n]+)*(?=\n\n)/, block) if text.start_with?("#{HEADING}\n")

    "#{block}\n\n#{text}"
  end

  def self.description(kind, original)
    if kind == :billing
      note = '本人钱包、实付与流量入账、计费倍率或保底扣量有差异时，也进入本场景核对。'
      return original.include?(note) ? original : "#{original}#{note}"
    end
    return original unless kind == :catalog

    original.sub('这类问题答案在 FAQ 知识库里，必须用 FAQ Lookup 直接回答，不要走工单或人工。',
                 '一般规则用 FAQ，当前价格、活动与个人权益先用对应的实时工具核对。')
  end
end
